import { createRenderer } from '@viewstem/svelte';
import { registerComponents } from '@viewstem/svelte-ui';
import { button } from '@viewstem/svelte-ui/shadcn/button';
import '@viewstem/svelte-ui/shadcn/styles.css';

export async function mountApp(
  target: HTMLElement,
  services: { save?: (name: string) => Promise<void> } = {},
): Promise<{ dispose: () => void | Promise<void> }> {
  const renderer = createRenderer();
  try {
    registerComponents(renderer, [button]);
    const mounted = await renderer.mount({
      target,
      view: {
        render: {
          id: 'start',
          componentRef: 'shadcn.Button',
          inputs: { text: 'Start' },
        },
      },
    });
    await mounted.initialComplete;

    let disposal: Promise<void> | undefined;
    return {
      dispose: () => (disposal ??= (async () => {
        try {
          await mounted.dispose();
        } finally {
          await renderer.dispose();
        }
      })()),
    };
  } catch (error) {
    await renderer.dispose();
    throw error;
  }
}

import { createRenderer } from '@viewstem/svelte';
import { registerComponents } from '@viewstem/svelte-ui';
import { button } from '@viewstem/svelte-ui/shadcn/button';
import '@viewstem/svelte-ui/shadcn/styles.css';

export async function mountApp(target: HTMLElement, services: {save?: (name:string)=>Promise<void>} = {}): Promise<{dispose:()=>void|Promise<void>}> {
  const renderer = createRenderer();
  try {
    registerComponents(renderer, [button]);
    const mounted = await renderer.mount({
      target,
      view: {
        render: {
          id: 'start',
          componentRef: 'shadcn.Button',
          inputs: { text: 'Start', type: 'button' },
        },
      },
    });
    const report = await mounted.initialComplete;
    if (report.queryErrors.length) throw report.queryErrors[0].error;
    return {
      dispose: async () => {
        try {
          await mounted.dispose();
        } finally {
          await renderer.dispose();
        }
      },
    };
  } catch (error) {
    await renderer.dispose();
    throw error;
  }
}

