import { createRenderer } from '@viewstem/svelte';
import { registerComponents } from '@viewstem/svelte-ui';
import { input } from '@viewstem/svelte-ui/shadcn/input';
import { button } from '@viewstem/svelte-ui/shadcn/button';
import { typography } from '@viewstem/svelte-ui/shadcn/typography';

export async function mountApp(target: HTMLElement, services: {save?: (name:string)=>Promise<void>} = {}): Promise<{dispose:()=>void|Promise<void>}> {
  const renderer = createRenderer();
  try {
    registerComponents(renderer, [input, button, typography]);
    renderer.registry.registerAction({
      kind: 'Action', id: 'saveName', spec: { ports: {
        name: { kind: 'Value', schema: { type: 'string' }, required: true },
        result: { kind: 'State', schema: { type: 'string' }, required: true },
        saved: { kind: 'State', schema: { type: 'boolean' }, required: true },
      } },
    }, async ({ inputs, signal }) => {
      await services.save?.(inputs.name);
      if (!signal.aborted) {
        inputs.result.write(`Saved: ${inputs.name}`);
        inputs.saved.write(true);
      }
    });
    const mounted = await renderer.mount({ target, view: {
      states: {
        name: { kind: 'State', schema: { type: 'string' }, initial: '' },
        result: { kind: 'State', schema: { type: 'string' }, initial: '' },
        saved: { kind: 'State', schema: { type: 'boolean' }, initial: false },
      },
      render: { id: 'form', componentRef: 'shadcn.Typography', inputs: { as: 'div' }, slots: { default: [
        { id: 'name', componentRef: 'shadcn.Input', inputs: { 'aria-label': 'Name', value: { '@path': '/states/name' } }, on: {
          input: { action: { ports: {
            target: { kind: 'State', schema: { type: 'string' }, required: true },
            next: { kind: 'Value', schema: { type: 'string' }, required: true },
          }, steps: [{ kind: 'SetState', target: { '@path': '/ports/target' }, value: { '@path': '/ports/next' } }] }, inputs: { target: { '@path': '/states/name' }, next: { '@path': '/event/value' } } },
        } },
        { id: 'save', componentRef: 'shadcn.Button', inputs: { text: 'Save', type: 'button' }, on: {
          click: { actionRef: 'saveName', inputs: { name: { '@path': '/states/name' }, result: { '@path': '/states/result' }, saved: { '@path': '/states/saved' } } },
        } },
        { id: 'result', componentRef: 'shadcn.Typography', when: { '@path': '/states/saved' }, inputs: { as: 'p', text: { '@path': '/states/result' } } },
      ] } },
    } });
    await mounted.initialComplete;
    return { dispose: () => renderer.dispose() };
  } catch (error) {
    await renderer.dispose();
    throw error;
  }
}

